const MANDANA_PAINTING_INFO={title:"Mandana Painting",region:"Rajasthan",state:"Rajasthan, India",tradition:"Wall and floor folk art",practitioners:"Meena tribe women (historically); rural Rajasthani women today",languages:["Hadoti","Rajasthani","Hindi"],giStatus:"Documented folk tradition (not GI-tagged as of 2026)",summary:"Mandana is a decorative wall and floor painting tradition practiced by women in the rural villages of Rajasthan. Drawn freehand with white chalk or khariya paste on a red-clay geru background, Mandana designs mark festivals (Diwali, Holi), weddings, harvests, and the birth of a child. The art is seasonal and ephemeral — redrawn on the walls and courtyards of the home for each occasion, then washed away by the next monsoon."},HISTORICAL_BACKGROUND=[{heading:"Origins in Rural Rajasthan",body:"Mandana painting is one of the oldest surviving folk-art traditions of Rajasthan, practised for centuries by the women of the Meena tribal community and by rural Rajasthani women more broadly. The word 'Mandana' comes from the Hindi/Sanskrit root 'mandan', meaning 'to decorate' or 'to adorn'. Unlike court painting traditions (such as the Mewar or Marwar schools), Mandana was never a profession — it was a household craft, passed from mother to daughter, created by women for the home."},{heading:"A Threshold and Wall Tradition",body:"Mandana designs are painted on two surfaces: the walls (deewar) and the floors (chowk or aangan) of village homes. The floor designs — drawn in the central courtyard — mark sacred thresholds and are the most ephemeral, redrawn for every festival. The wall designs, often framing doorways and windows, are more elaborate and may survive for months before being repainted."},{heading:"Ritual Function",body:"Mandana is fundamentally a ritual art. The designs are not decorative for their own sake — they invoke protective and auspicious forces. A Mandana drawn at the threshold of the home is believed to ward off the evil eye (nazar) and welcome Lakshmi, the goddess of prosperity. Mandana drawn for a wedding invokes fertility and marital blessing; Mandana drawn for the harvest celebrates the grain goddess Annapurna."},{heading:"The Monsoon Cycle",body:"The traditional rhythm of Mandana follows the agricultural year. The most elaborate Mandana are drawn for Diwali (October–November), when every household repaints its walls and courtyards. Holi (March) brings another wave of fresh Mandana. After the monsoon rains of June–September wash away the previous year's designs, the women repaint — a cycle of creation, dissolution, and recreation that has continued for generations."},{heading:"Modern Recognition",body:"Mandana painting began receiving wider academic and artistic attention in the mid-20th century through the work of folklorists and designers who documented the motifs and their meanings. In recent decades, Mandana designs have been adapted onto paper, fabric, and ceramic by contemporary artisans, allowing the tradition to reach urban markets and international audiences. However, the practice of drawing Mandana on village walls is declining as homes shift from mud-plaster to cement plaster, which does not hold the geru-and-khariya medium as well."}],TRADITIONAL_MOTIFS=[{name:"Ganesha Mandana",region:"Hadoti, Kota region",occasion:"Ganesh Chaturthi, Diwali",description:"A stylised silhouette of Lord Ganesha drawn at the threshold to invoke auspicious beginnings. Drawn freehand with thick white lines on a geru-red background.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Mandana_Ganesha.jpg/440px-Mandana_Ganesha.jpg"},{name:"Peacock Mandana",region:"Mewar (Udaipur, Bhilwara)",occasion:"Diwali, weddings",description:"The peacock (mor) is a symbol of beauty and fertility. Peacock Mandana are drawn in pairs flanking doorways, with their tail feathers fanned into a geometric grid.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Mandana_Peacock.jpg/440px-Mandana_Peacock.jpg"},{name:"Swastik Chowk",region:"All Rajasthan",occasion:"Diwali, weddings, births",description:"The swastik — an ancient Sanskrit symbol of well-being — is the most common Mandana motif. Drawn at the centre of the courtyard chowk with four arms radiating outward.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Mandana_Swastik.jpg/440px-Mandana_Swastik.jpg"},{name:"Lotus Mandana",region:"Marwar (Jodhpur, Pali)",occasion:"Diwali, Lakshmi Puja",description:"The lotus (kamal) is associated with Lakshmi, goddess of wealth. Lotus Mandana are drawn near the granary and the household shrine to invite prosperity.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Mandana_Lotus.jpg/440px-Mandana_Lotus.jpg"},{name:"Tree of Life (Khejri)",region:"Shekhawati, Sikar",occasion:"Harvest, Gangaur",description:"The Khejri tree (Prosopis cineraria) — sacred in Rajasthan — is drawn as a stylised Tree of Life, with symmetric branches, roots, and peacocks perched on top.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Mandana_Tree_of_Life.jpg/440px-Mandana_Tree_of_Life.jpg"},{name:"Bride and Groom (Vivah Mandana)",region:"Hadoti, Bundi",occasion:"Weddings",description:"Stylised bride and groom figures are drawn on the wall of the bridal chamber for the wedding ceremony. The figures flank a central mandap with the sacred fire.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Mandana_Vivah.jpg/440px-Mandana_Vivah.jpg"}],SYMBOL_MEANINGS=[{symbol:"Triangle (Trikona)",meaning:"Represents the trinity of Hindu cosmology (Brahma, Vishnu, Shiva) and the three gunas (qualities). Pointing upward it signifies male energy; downward, female energy.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Triangle.svg/120px-Triangle.svg.png"},{symbol:"Square (Chaturasra)",meaning:"Represents the earth and the material world. The four corners correspond to the four directions, the four vedas, and the four stages of life (ashramas).",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/Square.svg/120px-Square.svg.png"},{symbol:"Circle (Mandala)",meaning:"Represents the cosmos, wholeness, and the cyclical nature of time. Concentric circles drawn around a central dot symbolise the union of the individual soul with the universal.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/Circle.svg/120px-Circle.svg.png"},{symbol:"Swastika",meaning:"An ancient Sanskrit symbol of well-being (su + asti = 'it is well'). The four arms represent the four directions, the four vedas, and the cycle of life. Auspicious in Hindu, Buddhist, and Jain traditions for thousands of years.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Swastika.svg/120px-Swastika.svg.png"},{symbol:"Lotus (Kamala)",meaning:"Symbol of purity, beauty, and Lakshmi. The lotus grows from muddy water yet remains untouched by it — a metaphor for the spiritual aspirant living in the world without being contaminated by it.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Lotus.svg/120px-Lotus.svg.png"},{symbol:"Peacock (Mor)",meaning:"Symbol of beauty, fertility, and the cycle of seasons. The peacock's cry is said to herald the monsoon — making it a beloved motif in arid Rajasthan.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Peacock.svg/120px-Peacock.svg.png"},{symbol:"Diya (Lamp)",meaning:"Symbol of knowledge dispelling ignorance, and of Lakshmi's presence. Drawn in Mandana during Diwali to invite the goddess into the home.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Diya.svg/120px-Diya.svg.png"},{symbol:"Footprints (Charan)",meaning:"Symbol of Lakshmi's entry into the home. Drawn pointing inward at the threshold during Diwali — the goddess is believed to follow her footprints into the house, bringing prosperity.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Footprints.svg/120px-Footprints.svg.png"}],MATERIALS_CATALOG=[{name:"Geru (Red Ochre)",description:"Red-coloured earth (Hematite-rich clay) used as the base background for Mandana. Sourced from riverbeds and ground into a fine powder, mixed with water to form a paste, and applied to the plastered wall or floor as a smooth red base.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Red_ochre.jpg/200px-Red_ochre.jpg"},{name:"Khariya (Chalk / Limestone)",description:"White chalk powder used to draw the designs. Mixed with water to form a smooth paste, then applied with a cotton rag or brush. The contrast of white-on-red is the defining visual characteristic of Mandana.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Chalk.jpg/200px-Chalk.jpg"},{name:"Bamboo Sticks (Kalam)",description:"Sharpened bamboo sticks used as pens (kalam) to draw the fine white lines. The artist dips the bamboo tip into the khariya paste and traces freehand, without any preparatory sketch.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Bamboo_sticks.jpg/200px-Bamboo_sticks.jpg"},{name:"Cotton Rag (Pothi)",description:"A folded cotton rag is used to apply the larger background fields of red geru and to fill in broader white areas. The rag is also used to wipe away mistakes and to smudge edges for soft transitions.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Cotton_rag.jpg/200px-Cotton_rag.jpg"},{name:"Cow Dung & Mud Plaster",description:"The traditional wall surface is a smooth plaster of cow dung and clay, applied by hand. This surface holds the geru base coat beautifully — cement plaster, increasingly common in modern homes, does not.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Cow_dung.jpg/200px-Cow_dung.jpg"},{name:"Brush (Büjr)",description:"For finer work, a brush made of squirrel or goat hair is used. The brush (locally called büjr) is bound to a bamboo handle with cotton thread and is prized for its ability to hold a fine point.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Squirrel_brush.jpg/200px-Squirrel_brush.jpg"}],GALLERY_ITEMS=[{title:"Diwali Mandana on Courtyard Floor",region:"Kota, Hadoti",year:"Contemporary (c. 2020)",description:"A large Diwali Mandana drawn on the central courtyard (chowk) of a village home. The design features a central swastik surrounded by lotus petals, peacocks, and a border of footprints invoking Lakshmi.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Mandana_Diwali_Chowk.jpg/440px-Mandana_Diwali_Chowk.jpg",category:"floor"},{title:"Wall Mandana with Peacock Motif",region:"Bhilwara, Mewar",year:"Contemporary (c. 2018)",description:"A wall Mandana flanking a doorway, featuring paired peacocks with fanned tail-feathers. The design was painted for a wedding and remained on the wall for several months.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Mandana_Wall_Peacock.jpg/440px-Mandana_Wall_Peacock.jpg",category:"wall"},{title:"Ganesha Threshold Mandana",region:"Jaipur, Dhundhar",year:"Contemporary (c. 2022)",description:"A Ganesha Mandana drawn at the threshold of the home for Ganesh Chaturthi. The figure is stylised into a near-geometric silhouette, drawn with thick white khariya on geru red.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Mandana_Ganesha_Threshold.jpg/440px-Mandana_Ganesha_Threshold.jpg",category:"threshold"},{title:"Vivah (Wedding) Mandana",region:"Bundi, Hadoti",year:"Contemporary (c. 2019)",description:"Stylised bride and groom figures painted on the wall of the bridal chamber for the wedding ceremony. A central mandap with the sacred fire is drawn between them.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Mandana_Vivah_Wall.jpg/440px-Mandana_Vivah_Wall.jpg",category:"wall"},{title:"Harvest Mandana with Grain Goddess",region:"Sikar, Shekhawati",year:"Contemporary (c. 2021)",description:"A Mandana drawn for the harvest festival, depicting the grain goddess Annapurna seated on a lotus, surrounded by stylised sheaves of wheat and the Tree of Life.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Mandana_Harvest.jpg/440px-Mandana_Harvest.jpg",category:"floor"},{title:"Holi Mandana with Floral Border",region:"Udaipur, Mewar",year:"Contemporary (c. 2020)",description:"A bright Mandana drawn for Holi, featuring an elaborate floral border and a central lotus. The design was drawn on a freshly re-plastered wall after the monsoon.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Mandana_Holi.jpg/440px-Mandana_Holi.jpg",category:"wall"}],GALLERY_CATEGORIES=[{id:"all",label:"All"},{id:"floor",label:"Floor Mandana"},{id:"wall",label:"Wall Mandana"},{id:"threshold",label:"Threshold Mandana"}],REFERENCES_LIST=[{title:"Mandana: The Folk Art of Rajasthan",author:"Mistry, Jyotindra",publisher:"Mapin Publishing",year:1989,url:"https://www.mapinpub.in/"},{title:"Painted Myths of Creation: Folk and Tribal Art of India",author:"Jain, Jyotindra",publisher:"Lustre Press",year:1984,url:"https://en.wikipedia.org/wiki/Jyotindra_Jain"},{title:"Rajasthan Folk Arts — Mandana Painting",author:"Indian Government Ministry of Culture",publisher:"Centre for Cultural Resources and Training (CCRT)",year:2015,url:"https://ccrtindia.gov.in/"},{title:"Wikipedia: Mandana painting",author:"Wikipedia contributors",publisher:"Wikipedia",year:2024,url:"https://en.wikipedia.org/wiki/Mandana_painting"},{title:"The Painted World of the Meenas",author:"Cooper, Ilay",publisher:"Prakash Books",year:2002,url:"https://en.wikipedia.org/wiki/Meena_(tribe)"},{title:"Folk and Tribal Art of India — A Bibliography",author:"National Museum, New Delhi",publisher:"National Museum Institute",year:2010,url:"https://nationalmuseumindia.gov.in/"}];"undefined"!=typeof window&&(window.MANDANA_DATA={info:MANDANA_PAINTING_INFO,history:HISTORICAL_BACKGROUND,motifs:TRADITIONAL_MOTIFS,symbols:SYMBOL_MEANINGS,materials:MATERIALS_CATALOG,gallery:GALLERY_ITEMS,galleryCategories:GALLERY_CATEGORIES,references:REFERENCES_LIST}),"undefined"!=typeof module&&module.exports&&(module.exports={MANDANA_PAINTING_INFO:MANDANA_PAINTING_INFO,HISTORICAL_BACKGROUND:HISTORICAL_BACKGROUND,TRADITIONAL_MOTIFS:TRADITIONAL_MOTIFS,SYMBOL_MEANINGS:SYMBOL_MEANINGS,MATERIALS_CATALOG:MATERIALS_CATALOG,GALLERY_ITEMS:GALLERY_ITEMS,GALLERY_CATEGORIES:GALLERY_CATEGORIES,REFERENCES_LIST:REFERENCES_LIST});